import { delegate } from 'kerfjs';
import type { SafeHtml } from 'kerfjs';
import { PageHeader } from '@kerfjs/ui/page-header';
import { EmptyState } from '@kerfjs/ui/empty-state';
import { StateBanner } from '@kerfjs/ui/state-banner';
import { LoadingSpinner } from '@kerfjs/ui/loading-spinner';
import '@kerfjs/ui/layout.css';
import './task-workspace.css';

export interface Task { id: string; title: string; owner: string; status: string }
export function mountTaskWorkspace(root: HTMLElement, paint: (content: SafeHtml) => void, api: { list(signal: AbortSignal): Promise<Task[]>; create(): void }) {
  let items: Task[] | null = null;
  let pending = false;
  let failed = false;
  let disposed = false;
  let request: AbortController | undefined;
  const render = () => paint(<section class="task-workspace kui-layout">
    <PageHeader title="Release tasks" action={<button class="task-button" type="button" data-action="tasks-refresh" disabled={pending}>Refresh</button>} />
    <div class="task-workspace__body kui-scroll-owner kui-pane-body kui-section-stack" tabindex="0" aria-label="Release task content">
      {failed && <StateBanner tone="danger" urgency="alert" title={items === null ? 'Tasks could not be loaded' : 'Tasks could not be refreshed'} detail={items === null ? 'Check your connection and try again.' : 'Saved results are still shown below. Try again when the connection recovers.'} action={<button class="task-button" type="button" data-action="tasks-retry" disabled={pending}>{pending ? 'Retrying…' : 'Retry'}</button>} />}
      {pending && items !== null && <StateBanner tone="info" title="Showing saved results" detail="Refreshing in the background." action={<LoadingSpinner label="Refreshing release tasks" />} />}
      {items === null ? (pending ? <EmptyState title="Loading release tasks" detail="Your tasks will appear here." busy /> : <EmptyState title="No task data available" detail="Use Retry above to load the workspace." />) :
        items.length === 0 ? <EmptyState title="No release tasks" detail="Create the first task for this milestone." action={<button class="task-button" type="button" data-action="tasks-create">Create task</button>} /> :
        <ul class="task-list" aria-label="Release tasks">{items.map(item => <li data-task-id={item.id}><strong>{item.title}</strong><span class="kui-inline-metadata">{item.status} · {item.owner}</span></li>)}</ul>}
      <p role="status" aria-live="polite" aria-atomic="true">{!pending && !failed && items !== null ? items.length + (items.length === 1 ? ' task loaded.' : ' tasks loaded.') : ''}</p>
    </div>
  </section>);
  async function refresh() {
    if (pending || disposed) return;
    pending = true;
    // Preserve items and any important error until successful recovery.
    request = new AbortController();
    render();
    try {
      const next = await api.list(request.signal);
      if (disposed) return;
      items = next; failed = false;
    } catch (error) {
      if (disposed || (error instanceof DOMException && error.name === 'AbortError')) return;
      failed = true;
    } finally {
      if (!disposed) { pending = false; render(); }
    }
  }
  const offActions = delegate(root, 'click', '[data-action]', (_event, button) => {
    if (button.dataset.action === 'tasks-refresh' || button.dataset.action === 'tasks-retry') void refresh();
    if (button.dataset.action === 'tasks-create') api.create();
  });
  void refresh();
  return { refresh, dispose() { disposed = true; request?.abort(); offActions(); } };
}

