.task-workspace { display: grid; grid-template-rows: auto minmax(0, 1fr); height: 100%; min-height: 0; min-width: 0; background: var(--kui-color-surface); color: var(--kui-color-text); }
.task-workspace__body { overscroll-behavior: contain; }
.task-list { list-style: none; margin: 0; padding: 0; }
.task-list li { display: grid; gap: var(--kui-layout-metadata-gap); padding-block: var(--kui-space-s); border-block-end: 1px solid var(--kui-color-border); overflow-wrap: anywhere; }
.task-button { font: inherit; min-height: 2.5rem; border: 1px solid var(--kui-color-border); border-radius: var(--kui-radius-m); padding: var(--kui-space-xs) var(--kui-space-s); color: var(--kui-color-text); background: var(--kui-color-surface); }
.task-button:focus-visible, .task-workspace__body:focus-visible { outline: var(--kui-focus-ring); outline-offset: 2px; }
.task-button:disabled { cursor: wait; }
